import pytest
from isort.output import sorted_imports
from unittest.mock import Mock


def test_sorted_imports_no_imports():
    parsed = Mock()
    parsed.import_index = -1
    parsed.lines_without_imports = ["print('Hello World')"]
    assert sorted_imports(parsed) == "print('Hello World')"


def test_sorted_imports_with_imports():
    parsed = Mock()
    parsed.import_index = 0
    parsed.lines_without_imports = ["print('Hello World')"]
    parsed.imports = {'no_sections': {'straight': {'os': 'import os'}, 'from': {}}}
    expected_output = "import os\nprint('Hello World')"
    assert sorted_imports(parsed) == expected_output


def test_sorted_imports_multiple_imports():
    parsed = Mock()
    parsed.import_index = 0
    parsed.lines_without_imports = ["print('Hello World')"]
    parsed.imports = {
        'no_sections': {'straight': {'os': 'import os', 'sys': 'import sys'}, 'from': {}}
    }
    expected_output = "import os\nimport sys\nprint('Hello World')"
    assert sorted_imports(parsed) == expected_output


def test_sorted_imports_section_handling():
    parsed = Mock()
    parsed.import_index = 0
    parsed.lines_without_imports = ["print('Hello World')"]
    parsed.imports = {
        'FUTURE': {'straight': {}, 'from': {}},
        'no_sections': {'straight': {'os': 'import os'}, 'from': {}}
    }
    expected_output = "import os\nprint('Hello World')"
    assert sorted_imports(parsed) == expected_output

